class ConnectGame:
    def __init__(self, board):
        self.board = [line.strip() for line in board.splitlines()]

    def get_winner(self):
        rows = len(self.board)
        cols = len(self.board[0]) if rows else 0

        # X plays from left to right: start on the left edge, reach the right edge.
        if self._reaches(
            "X",
            [(r, 0) for r in range(rows)],
            lambda r, c: c == cols - 1,
        ):
            return "X"

        # O plays from top to bottom: start on the top edge, reach the bottom edge.
        if self._reaches(
            "O",
            [(0, c) for c in range(cols)],
            lambda r, c: r == rows - 1,
        ):
            return "O"

        return ""

    def _reaches(self, player, start_cells, goal):
        visited = set()
        stack = [
            cell for cell in start_cells if self.board[cell[0]][cell[1]] == player
        ]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            if goal(r, c):
                return True
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < len(self.board)
                        and 0 <= nc < len(self.board[nr])
                        and (nr, nc) not in visited
                        and self.board[nr][nc] == player
                    ):
                        stack.append((nr, nc))
        return False

